      "Make the mango layer: put mango, lime juice and maple/honey if using into a small pan. Cook on low-medium for 4-5 minutes until soft and glossy. Mash lightly to make a chunky compote, then cool.",
      "Build the jars with chia pudding, mango compote, more chia pudding and a final mango spoonful.",
      "Chill for at least 4 hours, ideally overnight. The pudding should be spoonable and thick.",
      "Add toasted coconut and seeds just before eating so they stay crunchy."
