          "air_fryer: Air fry at 180C for 5-7 minutes, turning halfway. Use a cocktail stick to hold closed if needed.",
          "microwave_reheat: Microwave from chilled for 1.5-2.5 minutes until hot, then crisp in a dry pan or air fryer if possible. From frozen, microwave 4-6 minutes then crisp.",
