      "Roast for 22-25 minutes, turning once halfway. The peppers should be soft and a little charred at the edges, the onion should be sweet and the chickpeas should look slightly crisp.",
      "Make the couscous while the tray roasts. Put the dry couscous in a heatproof bowl, pour over the hot stock, cover with a plate and leave for 5 minutes. Fluff with a fork, then stir through lemon zest, lemon juice and chopped herbs.",
      "Combine for meal prep. Divide the couscous between 4 tubs, then top with the roasted chickpeas and vegetables. Do not stir in the sauce yet; it can make the couscous heavy in the fridge.",
      "Pack 30g SA1 Lemon Garlic Tahini Sauce for a creamy mild finish, or 30g SA8 Harissa Lemon Dressing for extra smoky heat. Add the sauce after reheating or just before eating cold.",
