    "steps": [
      "Cook the pasta in a large pan of boiling salted water until just tender. For pasta salad, cook it only to al dente; if it is too soft now, it will become mushy after chilling. Drain and rinse briefly under cold water to stop the cooking.",
      "Make the dressing in the bottom of a large mixing bowl. Add the olive oil, lemon zest, lemon juice, grated garlic, oregano and black pepper. Whisk with a fork so the garlic spreads through the dressing instead of clumping in one bite.",
      "Add the drained pasta to the dressing while it is still slightly warm. Toss well so the pasta absorbs the lemon-garlic flavour before the tuna and vegetables go in.",
      "Prepare the mix-ins. Drain the tuna, halve the tomatoes, slice the olives, rinse the capers and chop the basil or parsley. Break the tuna into large flakes rather than mashing it.",
      "Fold the tuna, tomatoes, olives, capers and herbs through the pasta. Taste and adjust with more lemon, pepper or a pinch of salt if needed. Capers and olives are salty, so season at the end.",
      "If using SA22 Sundried Tomato Pesto, stir half through the pasta for richness and pack the rest separately for adding just before eating. This keeps the pasta from becoming dry.",
      "Portion into lunchboxes at about 380-420g each. Chill before closing the lids fully if the pasta is still warm, otherwise condensation will drip back into the box.",
      "Eat cold from the fridge or let it sit at room temperature for 10 minutes before eating. This pasta salad is not ideal for freezing because the tomatoes and tuna texture suffer."
    ],
