      "Serve with rice and steamed greens. Add SA10 Soy Ginger Dressing to cucumber salad, or SA15 Sweet Chilli Lime Sauce if you want more glaze.",
      "For batch cooking, pack sauce-coated chicken and rice together, but keep crunchy salad or sesame toppings separate."
