      "Stir the couscous again and taste it. Add lemon juice, herbs, salt or olive oil until it tastes bright, not dry.",
      "Serve each portion with salmon, herby couscous and salad. Drizzle SA1 Lemon Garlic Tahini Sauce over the couscous or add SA12 Green Herb Sauce for a lighter finish.",
      "For meal prep, cool the salmon before closing the tub. Eat chilled or reheat gently; salmon can dry out if microwaved too long."
