      "Mix harissa, lemon juice, oil, garlic, cumin, salt and pepper in a bowl. Taste a tiny bit of the marinade; it should be bold because it has to season chicken, chickpeas and vegetables.",
      "Add chicken pieces and coat well. If you have time, marinate for 30 minutes. If not, continue straight away.",
