      "Stir in oat cream, soya cream or cashew cream. Keep the heat gentle so the sauce stays smooth. Add a splash of pasta water if too thick.",
      "Return chicken to the pan and simmer for 2-3 minutes. Add spinach if using and stir until wilted.",
