      "Heat the oven to 200C / 180C fan, or preheat the air fryer to 190C. Line a tray with baking paper if oven-roasting.",
      "Tip the chickpeas into a bowl and add the olive oil. Toss until every chickpea has a light glossy coating. Add SP5, optional SP4, smoked paprika, garlic powder, salt and optional brown sugar. Toss again until the chickpeas look evenly speckled with seasoning.",
