      "For the best flavour, make a quick berry compote. Put frozen berries, honey or maple and lemon juice in a small pan over medium heat. Cook for 5-8 minutes, stirring often, until the berries collapse and the juices look glossy.",
      "Stir in chia seeds if using, then cool fully. The compote thickens as it cools. Do not layer hot compote onto yoghurt or the pot will turn watery.",
      "Stir vanilla into the coconut yoghurt if using. Taste it; add a little extra sweetener only if your yoghurt is very sharp.",
      "Divide half the yoghurt between 4 pots. Add a spoonful of berry compote, then the remaining yoghurt. Finish with another spoonful of compote on top.",
