      "Marinate for at least 20 minutes, or cover and chill up to 12 hours. A longer marinade gives deeper flavour, especially if using chicken thighs.",
      "Thread chicken onto skewers, adding pepper chunks if using. Do not squash the pieces tightly together; small gaps help the heat cook the chicken evenly.",
