      "Mix salsa, tomatoes, sweetcorn, spring onion, lime juice, optional SP17, salt and black pepper in a bowl. Taste and adjust with extra lime or seasoning.",
      "If using avocado pieces, toss them with a little extra lime to slow browning. If making pots for two days, use SA16 separately instead of diced avocado for better colour.",
      "Divide salsa mixture between 4 pots. Add eggs on top so they do not get crushed.",
      "Add avocado or SA16 just before eating if possible. Pack tortilla chips separately if using so they stay crisp.",
      "For a smoky version, add 1 tsp SA6 Chipotle Lime Sauce to each pot."
