          "Air fryer eggs: Air fry whole eggs at 130C for 13-15 mins, then ice-cool before peeling.",
          "Microwave: Not for whole eggs in shell. Reheat peeled eggs only if chopped, 20-30 seconds, but this pot is best cold.",
