      "Lift chicken from the marinade and toss in the seasoned cornflour. Press the coating onto each piece. Shake off heavy excess so the coating crisps instead of turning powdery.",
      "For air fryer or oven cooking, toss the coated chicken with oil or spray well. Dry patches of cornflour need a little oil to turn golden.",
      "Cook using your chosen route until crisp at the edges and steaming hot in the centre. Turn halfway so both sides colour.",
      "If using onion, pepper and chilli, stir-fry them quickly in a hot pan for 2-3 minutes, then toss with the cooked chicken and a pinch more SP15.",
