      "Cool the pineapple completely. Do not layer it hot or it will loosen the yoghurt and make the jar watery.",
      "Mix coconut yoghurt with vanilla and optional icing sugar or honey. Taste it: it should be lightly sweet, not sugary, because the cake and pineapple already bring sweetness.",
      "Add a layer of ginger cake cubes to each 0.5L jar. Spoon over a little pineapple syrup so the cake becomes moist but not flooded.",
      "Add a layer of pineapple, then a layer of yoghurt. Repeat with more cake and pineapple if the jar has space, finishing with yoghurt and a few crumbs or toasted coconut.",
      "Chill for at least 1 hour before eating. For the neatest meal-prep jars, keep the toasted coconut in a small separate pot and add it just before serving."
