          "No churn freezer: Freeze in a shallow tub and stir every 45 minutes for the first 2-3 hours for a smoother texture.",
          "Storage: Freeze up to 1 month. Soften 10-15 minutes before scooping.",
          "Microwave: Do not microwave; soften at room temp."
