      "Add the ice and blend again until thick and cold. If the blender struggles, add 30-50ml more oat milk and pulse rather than running it continuously.",
      "Taste for chocolate-orange balance. Add a little more orange zest for fragrance, cocoa for deeper chocolate, or syrup if the cocoa tastes too bitter.",
